function assemble_official_modular()
%ASSEMBLE_OFFICIAL_MODULAR Build editable algorithms inside the Simulink file.
root=stampfly_project_root();addpath(root,fullfile(root,'models'));init_official;
model='StampFly_Official_Bench400';open_system(stampfly_model_file(model));
assert(library.settingsLookup().gatePass);
edit(model,'blk_72',{struct('op','delete','target','blk_108'),struct('op','delete','target','blk_109'),struct('op','delete','target','blk_110'),struct('op','delete','target','blk_111'),struct('op','delete','target','blk_112'),struct('op','delete','target','blk_113'),struct('op','delete','target','blk_114'),struct('op','delete','target','blk_115'),struct('op','delete','target','blk_116')},'incremental');
axes=chart(model,'blk_72','IMUAxisConversion',{'accelMps2','single';'gyroRps','single'},{'a','single';'g','single'},strjoin({'function [a,g]=stepFn(accelMps2,gyroRps)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','            a=accelMps2([2 1 3])/single(9.80665);a(3)=-a(3);','            g=gyroRps([2 1 3]);g(3)=-g(3);','end'},newline),'[a,g]=stepFn(accelMps2,gyroRps);');
cal=chart(model,'blk_72','IMUBiasCalibration',{'a','single';'g','single';'mode','uint8'},{'offset','single';'count','uint16'},strjoin({'function [offset,count]=stepFn(a,g,mode)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','persistent Offset Count;','if isempty(Offset)','Offset=zeros(4,1,''single'');','Count=uint16(0);','end','            if mode==0,Offset(:)=single(0);Count=uint16(0);','            elseif mode==1 && Count<uint16(800)','                n=single(Count);Offset=(n*Offset+[g;a(3)])/(n+single(1));Count=Count+uint16(1);','            end','            offset=Offset;count=Count;','end'},newline),'[offset,count]=stepFn(a,g,mode);');
filter=chart(model,'blk_72','IMUFiltering',{'a','single';'g','single';'offset','single';'mode','uint8';'dt','single'},{'af','single';'gf','single';'azd','single'},strjoin({'function [af,gf,azd]=stepFn(a,g,offset,mode,dt)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','persistent Filter Accel Gyro Azd PreviousMode;','if isempty(Filter)','Filter=zeros(7,1,''single'');','Accel=zeros(3,1,''single'');','Gyro=zeros(3,1,''single'');','Azd=single(0);','PreviousMode=uint8(0);','end','            if mode==3 && mode~=PreviousMode,Filter(:)=single(0);end','            if mode>1','                for j=1:3','                    Filter(j)=filterStep(a(j),dt,single(0.003),Filter(j));','                    Filter(j+3)=filterStep(g(j)-offset(j),dt,single(0.003),Filter(j+3));','                end','                Filter(7)=filterStep(a(3)-offset(4),dt,single(0.1),Filter(7));','                Accel=Filter(1:3);Gyro=Filter(4:6);Azd=Filter(7);','            end','            af=Accel;gf=Gyro;azd=Azd;PreviousMode=mode;','end','','function s = filterStep(u,h,T,s)','%FILTERSTEP Exact Filter::update, including operation ordering.','%#codegen','s = s*T/(T+h) + u*h/(T+h);','end'},newline),'[af,gf,azd]=stepFn(a,g,offset,mode,dt);');
att=chart(model,'blk_72','MadgwickAttitude',{'rates','single';'accel','single';'mode','uint8';'reset','boolean'},{'a','single';'q','single'},strjoin({'function [a,q]=stepFn(rates,accel,mode,reset)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','persistent Q Angles;','if isempty(Q)','Q=single([1;0;0;0]);','Angles=zeros(3,1,''single'');','end','            if reset,Q=single([1;0;0;0]);end','            if mode>1,[Angles,Q]=madgwickStep(rates,accel,Q,false);end','            a=Angles;q=Q;','end','','function [attitude,q] = madgwickStep(rates,accel,q,reset)','%MADGWICKSTEP Official updateIMU with body-axis conventions and invSqrt.','% Rates rad/s and accel g in official body frame [forward;left;down].','% Madgwick is fixed 400 Hz even though other official filters use measured dt.','% Translation of lib/MdgwickAHRS/MadgwickAHRS.cpp; original license retained.','%#codegen','if reset, q=single([1;0;0;0]); end','q0=q(1);q1=q(2);q2=q(3);q3=q(4);','% Retain original rad->deg->rad conversion coefficients, including rounding.','g=rates([2 1 3])*single(180/pi);g(3)=-g(3);','g=g*single(0.0174533);gx=g(1);gy=g(2);gz=g(3);','a=accel([2 1 3]);a(3)=-a(3);ax=a(1);ay=a(2);az=a(3);','dq=single(0.5)*[-q1*gx-q2*gy-q3*gz; q0*gx+q2*gz-q3*gy; ...','    q0*gy-q1*gz+q3*gx; q0*gz+q1*gy-q2*gx];','if ax~=0 || ay~=0 || az~=0','    reciprocal=fastInvSqrt(ax*ax+ay*ay+az*az);','    ax=ax*reciprocal;ay=ay*reciprocal;az=az*reciprocal;','    q02=q0*q0;q12=q1*q1;q22=q2*q2;q32=q3*q3;','    q0x2=single(2)*q0;q1x2=single(2)*q1;q2x2=single(2)*q2;q3x2=single(2)*q3;','    q0x4=single(4)*q0;q1x4=single(4)*q1;q2x4=single(4)*q2;','    q1x8=single(8)*q1;q2x8=single(8)*q2;','    gradient=[q0x4*q22+q2x2*ax+q0x4*q12-q1x2*ay; ...','        q1x4*q32-q3x2*ax+single(4)*q02*q1-q0x2*ay-q1x4+q1x8*q12+q1x8*q22+q1x4*az; ...','        single(4)*q02*q2+q0x2*ax+q2x4*q32-q3x2*ay-q2x4+q2x8*q12+q2x8*q22+q2x4*az; ...','        single(4)*q12*q3-q1x2*ax+single(4)*q22*q3-q2x2*ay];','    reciprocal=fastInvSqrt(gradient(1)*gradient(1)+gradient(2)*gradient(2)+gradient(3)*gradient(3)+gradient(4)*gradient(4));','    gradient=gradient*reciprocal;','    dq=dq-single(0.1)*gradient;','end','q=q+dq*single(1/400);','reciprocal=fastInvSqrt(q(1)*q(1)+q(2)*q(2)+q(3)*q(3)+q(4)*q(4));q=q*reciprocal;','roll=atan2(q(1)*q(2)+q(3)*q(4),single(0.5)-q(2)*q(2)-q(3)*q(3));','pitch=asin(-single(2)*(q(2)*q(4)-q(1)*q(3)));','yaw=atan2(q(2)*q(3)+q(1)*q(4),single(0.5)-q(3)*q(3)-q(4)*q(4));','% Original getYaw adds 180 degrees; do not hide this offset.','attitude=[pitch*single(57.29578);roll*single(57.29578); ...','    -(yaw*single(57.29578)+single(180))]*single(pi/180);','end','','function y=fastInvSqrt(x)','i=typecast(x,''uint32'');i=uint32(hex2dec(''5f3759df''))-bitshift(i,-1);','y=typecast(i,''single'');half=single(0.5)*x;','y=y*(single(1.5)-half*y*y);y=y*(single(1.5)-half*y*y);','end'},newline),'[a,q]=stepFn(rates,accel,mode,reset);');
az=chart(model,'blk_72','VerticalAcceleration',{'azd','single';'mode','uint8';'dt','single'},{'az','single'},strjoin({'function [az]=stepFn(azd,mode,dt)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','persistent Az PreviousMode;','if isempty(Az)','Az=single(0);','PreviousMode=uint8(0);','end','            if mode==3 && mode~=PreviousMode,Az=single(0);end','            if mode>1,Az=filterStep(-azd,dt,single(0.1),Az);end','            az=Az;PreviousMode=mode;','end','','function s = filterStep(u,h,T,s)','%FILTERSTEP Exact Filter::update, including operation ordering.','%#codegen','s = s*T/(T+h) + u*h/(T+h);','end'},newline),'[az]=stepFn(azd,mode,dt);');
tof=chart(model,'blk_72','ToFHoldOutlierFilter',{'mm','int16';'fresh','uint8';'mode','uint8';'dt','single'},{'alt','single';'raw','int16'},strjoin({'function [alt,raw]=stepFn(mm,fresh,mode,dt)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','persistent History Range Raw Outlier Alt PreviousMode;','if isempty(History)','History=zeros(4,1,''int16'');','Range=int16(0);','Raw=int16(0);','Outlier=uint8(0);','Alt=single(0);','PreviousMode=uint8(0);','end','            if mode==3 && mode~=PreviousMode,History(:)=int16(0);Alt=single(0);end','            if mode>1','                if fresh~=0','                    Raw=mm;if mm>int16(20),Range=mm;end','                    delta=int32(Range)-int32(History(2));','                    if abs(delta)>int32(500) && Outlier<uint8(2)','                        extrap=int32(History(2))+idivide(int32(History(2))-int32(History(4)),int32(2),''fix'');','                        Range=int16(extrap);Outlier=Outlier+uint8(1);','                    else','                        Outlier=uint8(0);History(4)=History(3);History(3)=History(2);History(2)=Range;','                    end','                end','                Alt=filterStep(single(double(Range)/1000),dt,single(0.005),Alt);','            end','            alt=Alt;raw=Raw;PreviousMode=mode;','end','','function s = filterStep(u,h,T,s)','%FILTERSTEP Exact Filter::update, including operation ordering.','%#codegen','s = s*T/(T+h) + u*h/(T+h);','end'},newline),'[alt,raw]=stepFn(mm,fresh,mode,dt);');
kal=chart(model,'blk_72','AltitudeKalman',{'alt','single';'az','single';'mode','uint8';'dt','single';'parkingReset','boolean'},{'height','single';'velocity','single';'bias','single'},strjoin({'function [height,velocity,bias]=stepFn(alt,az,mode,dt,parkingReset)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','persistent State First PreviousMode;','if isempty(State)','State=kalmanInitial();','First=false;','PreviousMode=uint8(0);','end','            if parkingReset,[~,State]=kalmanStep(single(0),single(0),dt,true,State);end','            if mode==3 && mode~=PreviousMode,First=false;end','            if mode>1','                if First,[~,State]=kalmanStep(alt,az,dt,false,State);else,First=true;end','            end','            velocity=State.output(1);height=State.output(2);bias=State.output(3);PreviousMode=mode;','end','','function [y,s] = kalmanStep(z,acc,h,resetState,s)','%KALMANSTEP Direct translation of Alt_kalman::update, state [v;z;bias].','% Preserve reset(): covariance and public output reset, private x is retained.','%#codegen','if resetState','    s.P = single(100)*eye(3,''single''); s.output(:) = single(0);','else','    p=s.P; b=single(-0.01); f=single(1)+h*b;','    xp=[s.x(1)+(acc-s.x(3))*h;s.x(2)+s.x(1)*h;s.x(3)*f];','    pp=zeros(3,3,''single'');','    pp(1,1)=p(1,1)-h*(p(3,1)+p(1,3))+h*h*p(3,3)+h*h*single(0.01);','    pp(1,2)=h*(p(1,1)-p(3,2))-h*h*p(3,1)+p(1,2);','    pp(1,3)=f*(p(1,3)-h*p(3,3));','    pp(2,1)=h*(p(1,1)-p(2,3))-h*h*p(1,3)+p(2,1);','    pp(2,2)=h*h*p(1,1)+h*(p(2,1)+p(1,2))+p(2,2);','    pp(2,3)=f*(p(2,3)+h*p(1,3));','    pp(3,1)=f*(p(3,1)-h*p(3,3));','    pp(3,2)=f*(p(3,2)+h*p(3,1));','    pp(3,3)=f*f*p(3,3)+h*h;','    k=[pp(1,2);pp(2,2);pp(3,2)]/(pp(2,2)+single(0.004*0.004));','    e=z-xp(2); s.x=xp+k*e; s.output=s.x;','    s.P(1,:)=pp(1,:)-k(1)*pp(2,:);','    s.P(2,:)=pp(2,:)*(single(1)-k(2));','    s.P(3,:)=-k(3)*pp(2,:)+pp(3,:);','end','y=s.output;','end','','function s = kalmanInitial()','%#codegen','s = struct(''x'',zeros(3,1,''single''),''P'',single(100)*eye(3,''single''), ...','    ''output'',zeros(3,1,''single''));','end'},newline),'[height,velocity,bias]=stepFn(alt,az,mode,dt,parkingReset);');
flags=chart(model,'blk_72','SensorFlags',{'accel','single';'azd','single';'voltage','single';'mode','uint8';'altFlag','uint8';'velocity','single';'rawRange','int16';'dt','single';'parkingReset','boolean'},{'flags','uint8'},strjoin({'function [flags]=stepFn(accel,azd,voltage,mode,altFlag,velocity,rawRange,dt,parkingReset)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','persistent Norm Voltage OverG RangeFlag LowVoltage PreviousMode;','if isempty(Norm)','Norm=single(0);','Voltage=single(0);','OverG=uint8(0);','RangeFlag=uint8(0);','LowVoltage=uint8(0);','PreviousMode=uint8(0);','end','            if parkingReset,OverG=uint8(0);RangeFlag=uint8(0);end','            if mode==3 && mode~=PreviousMode,Norm=single(0);end','            if mode>1','                if (velocity>single(2) && altFlag~=0) || rawRange==0,RangeFlag=min(RangeFlag+uint8(1),uint8(20));else,RangeFlag=uint8(0);end','            end','            normA=sqrt(accel(1)*accel(1)+accel(2)*accel(2)+azd*azd);','            Norm=filterStep(normA,dt,single(.005),Norm);','            if Norm>single(2),OverG=uint8(1);end','            Voltage=filterStep(voltage,dt,single(.005),Voltage);','            if LowVoltage~=uint8(100)','                if Voltage<single(3.34),LowVoltage=LowVoltage+uint8(1);else,LowVoltage=uint8(0);end','                LowVoltage=min(LowVoltage,uint8(100));','            end','            flags=[OverG;RangeFlag;LowVoltage];PreviousMode=mode;','end','','function s = filterStep(u,h,T,s)','%FILTERSTEP Exact Filter::update, including operation ordering.','%#codegen','s = s*T/(T+h) + u*h/(T+h);','end'},newline),'[flags]=stepFn(accel,azd,voltage,mode,altFlag,velocity,rawRange,dt,parkingReset);');
diag=chart(model,'blk_72','SensorDiagnosticPack',{'az','single';'bias','single';'alt','single';'offset','single';'count','uint16'},{'diag','single'},strjoin({'function [diag]=stepFn(az,bias,alt,offset,count)','% 日本語の説明はブロック注釈とDescriptionを参照。','%#codegen','            diag=[az;bias;alt;offset;single(count)];','end'},newline),'[diag]=stepFn(az,bias,alt,offset,count);');
edit(model,'blk_72',{
wire('blk_75.y1',[axes '.u1']),wire('blk_76.y1',[axes '.u2']),wire([axes '.y1'],[cal '.u1']),wire([axes '.y2'],[cal '.u2']),wire('blk_80.y1',[cal '.u3']),wire([axes '.y1'],[filter '.u1']),wire([axes '.y2'],[filter '.u2']),wire([cal '.y1'],[filter '.u3']),wire('blk_80.y1',[filter '.u4']),wire('blk_82.y1',[filter '.u5']),wire([filter '.y2'],[att '.u1']),wire([filter '.y1'],[att '.u2']),wire('blk_80.y1',[att '.u3']),wire('blk_83.y1',[att '.u4']),wire([filter '.y3'],[az '.u1']),wire('blk_80.y1',[az '.u2']),wire('blk_82.y1',[az '.u3']),wire('blk_77.y1',[tof '.u1']),wire('blk_78.y1',[tof '.u2']),wire('blk_80.y1',[tof '.u3']),wire('blk_82.y1',[tof '.u4']),wire([tof '.y1'],[kal '.u1']),wire([az '.y1'],[kal '.u2']),wire('blk_80.y1',[kal '.u3']),wire('blk_82.y1',[kal '.u4']),wire('blk_84.y1',[kal '.u5']),wire([filter '.y1'],[flags '.u1']),wire([filter '.y3'],[flags '.u2']),wire('blk_79.y1',[flags '.u3']),wire('blk_80.y1',[flags '.u4']),wire('blk_81.y1',[flags '.u5']),wire([kal '.y2'],[flags '.u6']),wire([tof '.y2'],[flags '.u7']),wire('blk_82.y1',[flags '.u8']),wire('blk_84.y1',[flags '.u9']),wire([az '.y1'],[diag '.u1']),wire([kal '.y3'],[diag '.u2']),wire([tof '.y1'],[diag '.u3']),wire([cal '.y1'],[diag '.u4']),wire([cal '.y2'],[diag '.u5']),wire([att '.y1'],'blk_85.u1'),wire([filter '.y2'],'blk_86.u1'),wire([kal '.y1'],'blk_87.u1'),wire([kal '.y2'],'blk_88.u1'),wire([flags '.y1'],'blk_89.u1'),wire([att '.y2'],'blk_90.u1'),wire([diag '.y1'],'blk_91.u1')},'full');
model_check(model,'blk_72','["all"]');
save_system(model);

end

function ids=edit(model,scope,ops,layout)
% One scope per call; stop on any partial operation rather than hiding errors.
model_read(model,scope,'0');
r=char(model_edit(model,scope,jsonencode(ops),layout));
if ~startsWith(strtrim(r),'status: ok'),error('official:EditFailed','%s',r);end
matches=regexp(r,'(?m)^\s+(\w+): (blk_\d+)\s*$','tokens');ids=struct;
for k=1:numel(matches),ids.(matches{k}{1})=matches{k}{2};end
end
function op=add(type,name,ref,params)
op=struct('op','add_block','type',type,'name',name,'ref',ref,'params',params);
end
function op=wire(a,b)
op=struct('op','connect','target',[a ' -> ' b]);
end
function op=config(target,params)
op=struct('op','configure','target',target,'params',params);
end
function id=chart(model,parent,name,inputs,outputs,script,label)
ids=edit(model,parent,{add('Chart',name,'chart',struct)},'incremental');id=ids.chart;
ops={config(['chart:' model],struct('ActionLanguage','MATLAB'))};
for k=1:size(inputs,1)
    ops{end+1}=add('Data',inputs{k,1},['i' num2str(k)],struct('Scope','Input','DataType',inputs{k,2}));
end
for k=1:size(outputs,1)
    ops{end+1}=add('Data',outputs{k,1},['o' num2str(k)],struct('Scope','Output','DataType',outputs{k,2}));
end
ops{end+1}=struct('op','add_block','type','EMFunction','ref','function', 'params',struct('Script',script));
ops{end+1}=add('State','Calculate','calculate',struct('LabelString',['Calculate' newline 'en,du: ' label]));
ops{end+1}=struct('op','connect','target','? -> #calculate');
edit(model,id,ops,'full');
model_check(model,id,'["stateflow_lint"]');
end
